const [st, jayzeeDiff, pkg, wf] = await Promise.all([
  gm.git_status({}),
  gm.run_shell({ command: 'cd /workspace/cleetus && git --no-pager diff --stat -- .jayzee && git --no-pager diff -- .jayzee/update-engine-pin.py | head -c 3000' }),
  gm.read_file({ path: '/workspace/cleetus/package.json' }),
  gm.read_file({ path: '/workspace/cleetus/.github/workflows/publish.yml' })
]);
return { status: st, jayzeeDiff: jayzeeDiff.output, pkg: pkg.output, wf: wf.output };

const before = await gm.try(() => gm.playwriter_browsers({ action: 'list' }));
const code = `
const page = await context.newPage();
try {
  await page.goto('file:///workspace/cleetus/site/index.html', { waitUntil: 'load' });
  const title = await page.title();
  const h1 = await page.textContent('h1');
  const h2s = await page.$$eval('h2', (els) => els.map((e) => e.textContent.trim()));
  const rows = await page.$$eval('table tbody tr', (els) => els.length);
  const fontFamily = await page.evaluate(() => getComputedStyle(document.body).fontFamily);
  const borderBottom = await page.evaluate(() => getComputedStyle(document.querySelector('header')).borderBottomWidth);
  return { title, h1, h2s, rows, fontFamily, borderBottom };
} finally {
  await page.close();
}`;
const run = await gm.try(() => gm.playwriter_execute({ code, timeout: 60000 }));
return { before, run };

